// lib/pricing/engine.ts — SINGLE SOURCE OF TRUTH
import { Decimal } from 'decimal.js';
import { prisma } from '@/lib/prisma';

// Конфигурация Decimal.js: строгая точность, банковское округление
Decimal.set({ precision: 38, rounding: Decimal.ROUND_HALF_EVEN });

export function calculateSellPriceStrict(
  buyPrice: string | number,      // Принимаем строку или число
  markupBps: number,              // Базисные пункты (int)
  minMarginBps: number = 0        // AntiNegativeMargin floor
): { sellPrice: string; marginBps: number; valid: boolean } {
  const buy = new Decimal(buyPrice);
  const markup = new Decimal(markupBps).div(10000);
  const minMargin = new Decimal(minMarginBps).div(10000);

  // 1. Расчет цены с наценкой
  let sell = buy.mul(new Decimal(1).plus(markup));

  // 2. Применение Beautiful Rounding (математически чисто)
  sell = applyBeautifulRoundingDecimal(sell); // Реализация на Decimal.js

  // 3. Проверка AntiNegativeMargin НА ТОЧНЫХ ЧИСЛАХ
  const actualMargin = sell.minus(buy).div(buy);
  if (actualMargin.lt(minMargin)) {
    // Принудительное поднятие до минимальной маржи + округление
    sell = applyBeautifulRoundingDecimal(buy.mul(new Decimal(1).plus(minMargin)));
  }

  return {
    sellPrice: sell.toFixed(4), // Строка для Prisma Decimal
    marginBps: actualMargin.mul(10000).toFixed(0),
    valid: true
  };
}

// DB-LEVEL CONSTRAINT (Prisma Schema / Migration)
