export async function auditAdminImmutable(params: {
  action: AuditAction;
  entityType: string;
  entityId: string;
  refType: 'manual' | 'refund' | 'fee' | 'chargeback';
  refId: string;
  diff: Record<string, { old: any; new: any }>; // Структурированный diff
}) {
