  const lastLog = await prisma.auditLog.findFirst({
    where: { tenantId },
    orderBy: { createdAt: 'desc' },
    select: { currentHash: true }
  });

  const payload = JSON.stringify({ ...params, staffId, tenantId, ip, ua, timestamp: new Date().toISOString() });
  const prevHash = lastLog?.currentHash ?? 'genesis';
  const currentHash = createHash('sha256').update(payload + prevHash).digest('hex');

